// and edges) and the same cell structure.
func checkShapeIndexEqual(t *testing.T, want, got *ShapeIndex) {
	t.Helper()
	if !got.IsFresh() {
		t.Errorf("decoded index is not fresh")
	}
	if got.Len() != want.Len() || got.nextID != want.nextID {
		t.Fatalf("got Len %d nextID %d, want Len %d nextID %d", got.Len(), got.nextID, want.Len(), want.nextID)
	}
	for id, ws := range want.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Fatalf("shape %d missing after decode", id)
		}
		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
		}
		if gs.Dimension() != ws.Dimension() || gs.NumEdges() != ws.NumEdges() || gs.NumChains() != ws.NumChains() {
			t.Fatalf("shape %d: dimension/edges/chains mismatch", id)
		}
		for e := 0; e < ws.NumEdges(); e++ {
			if gs.Edge(e) != ws.Edge(e) {
				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
			}
		}
		for c := 0; c < ws.NumChains(); c++ {
			if gs.Chain(c) != ws.Chain(c) {
				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
			}
		}
		if gs.ReferencePoint() != ws.ReferencePoint() {
			t.Errorf("shape %d reference point = %v, want %v", id, gs.ReferencePoint(), ws.ReferencePoint())
		}
	}

	wi, gi := want.Iterator(), got.Iterator()
	for ; !wi.Done(); wi.Next() {
		if gi.Done() {
			t.Fatalf("decoded index has fewer cells")
		}
		if wi.CellID() != gi.CellID() {
			t.Fatalf("cell id = %v, want %v", gi.CellID(), wi.CellID())
		}
		wc, gc := wi.IndexCell(), gi.IndexCell()
		var wantClipped []*clippedShape
		for _, c := range wc.shapes {
			if want.Shape(c.shapeID) != nil {
